<?php
require_once __DIR__ . '/app.php'; require_login(); $me=current_user(); $username=trim((string)($_GET['u']??$me['username'])); $stmt=$conn->prepare('SELECT id,username,display_name,email,avatar_path,bio,created_at FROM users WHERE username=? LIMIT 1'); $stmt->bind_param('s',$username); $stmt->execute(); $profile=$stmt->get_result()->fetch_assoc(); if(!$profile){http_response_code(404);page_start('Profile not found');echo '<main class="content-wrap"><div class="empty-state card"><h2>Profile not found</h2><a href="explore.php">Back to Explore</a></div></main>';page_end();exit;}
$stmt=$conn->prepare('SELECT (SELECT COUNT(*) FROM posts WHERE user_id=?) posts_count,(SELECT COUNT(*) FROM follows WHERE followed_id=?) followers,(SELECT COUNT(*) FROM follows WHERE follower_id=?) following, EXISTS(SELECT 1 FROM follows WHERE follower_id=? AND followed_id=?) is_following'); $stmt->bind_param('iiiii',$profile['id'],$profile['id'],$profile['id'],$me['id'],$profile['id']);$stmt->execute();$stats=$stmt->get_result()->fetch_assoc();
$stmt=$conn->prepare('SELECT p.id,p.image_path,p.caption,p.created_at,(SELECT COUNT(*) FROM likes l WHERE l.post_id=p.id) likes,(SELECT COUNT(*) FROM comments c WHERE c.post_id=p.id) comments FROM posts p WHERE p.user_id=? ORDER BY p.created_at DESC');$stmt->bind_param('i',$profile['id']);$stmt->execute();$posts=$stmt->get_result();page_start($profile['display_name']);
?>
<main class="content-wrap profile-wrap"><section class="profile-hero card"><div class="profile-cover"></div><div class="profile-details"><img class="profile-avatar" src="<?= e(avatar(['avatar_path'=>$profile['avatar_path']])) ?>" alt="<?= e($profile['display_name']) ?>"><div class="profile-main"><div class="profile-title"><div><h1><?= e($profile['display_name']) ?></h1><p class="handle">@<?= e($profile['username']) ?></p></div><?php if($profile['id']===$me['id']): ?><a class="btn secondary" href="edit-profile.php">Edit profile</a><?php else: ?><form method="post" action="follow.php"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="user_id" value="<?= (int)$profile['id'] ?>"><input type="hidden" name="mode" value="<?= $stats['is_following']?'unfollow':'follow' ?>"><button class="btn <?= $stats['is_following']?'secondary':'primary' ?>" type="submit"><?= $stats['is_following']?'Following ✓':'＋ Follow' ?></button></form><?php endif; ?></div><p class="profile-bio"><?= nl2br(e($profile['bio'] ?: 'Still writing their story.')) ?></p><div class="stats-row"><span><strong><?= (int)$stats['posts_count'] ?></strong> posts</span><span><strong><?= (int)$stats['followers'] ?></strong> followers</span><span><strong><?= (int)$stats['following'] ?></strong> following</span><span class="joined">Joined <?= e(date('M Y',strtotime($profile['created_at']))) ?></span></div></div></div></section><div class="section-heading profile-post-heading"><div><span class="eyebrow muted">THEIR MOMENTS</span><h2>Posts<span class="heading-dot">.</span></h2></div></div><?php if($posts->num_rows===0): ?><div class="empty-state card"><div class="empty-icon">▧</div><h2>No posts yet.</h2><p>When they share a moment, you’ll find it here.</p></div><?php else: ?><div class="post-grid"><?php while($p=$posts->fetch_assoc()): ?><a class="grid-post" href="post.php?id=<?= (int)$p['id'] ?>"><img src="<?= e($p['image_path']) ?>" alt="Post by <?= e($profile['username']) ?>" loading="lazy"><span class="grid-overlay"><span>♥ <?= (int)$p['likes'] ?></span><span>◯ <?= (int)$p['comments'] ?></span></span></a><?php endwhile; ?></div><?php endif; ?></main>
<?php page_end(); ?>
